@startuml

class User {
  + UserID : int
  + Name : string
  + Email : string
  + Birthdate : date
}

class Account {
  + AccountID : int
  + AccountType : string
  + CompanyName : string
  + MonthlyFee : double
}

class Page {
  + PageName : string
  + Visits : int
}

class AdvertisementPage {
  + BounceRate : float
  + ClickThroughRate : float
  + ConversionRate : float
}

User "1" -- "*" Account
Account "1" -- "*" Page
Page "*" -- "0..1" AdvertisementPage

@enduml

